module clkgenerator(
    output clk
);
    parameter PERIOD = 10;

    reg clk_reg;
    initial begin
        clk_reg = 0;
    end

    always @(posedge clk_reg) begin
        if ($time >= ((PERIOD/2)*10)) begin
            clk_reg <= ~clk_reg;
        end
    end
    assign clk = clk_reg;
endmodule
